{
  "root": "wizard",
  "elements": [
    {
      "id": "wizard",
      "type": "Stack",
      "props": [
        {"key": "direction", "value": "vertical"},
        {"key": "gap", "value": "lg"}
      ],
      "children": ["wizard-header", "wizard-progress", "wizard-steps", "step-panel", "wizard-footer"]
    },
    {
      "id": "wizard-header",
      "type": "Stack",
      "props": [
        {"key": "direction", "value": "vertical"},
        {"key": "gap", "value": "sm"}
      ],
      "children": ["wizard-title", "wizard-subtitle"]
    },
    {
      "id": "wizard-title",
      "type": "Heading",
      "props": [
        {"key": "text", "value": "Set up your Northwind account"},
        {"key": "level", "value": "h1"}
      ],
      "children": []
    },
    {
      "id": "wizard-subtitle",
      "type": "Text",
      "props": [
        {"key": "text", "value": "Three quick steps and you're in. Create your account, pick how you want to work, and you're done — it takes about two minutes."},
        {"key": "variant", "value": "lead"}
      ],
      "children": []
    },
    {
      "id": "wizard-progress",
      "type": "Progress",
      "props": [
        {"key": "label", "value": "Step 1 of 3 — Account"},
        {"key": "value", "value": "33"}
      ],
      "children": []
    },
    {
      "id": "wizard-steps",
      "type": "Stack",
      "props": [
        {"key": "direction", "value": "horizontal"},
        {"key": "gap", "value": "sm"},
        {"key": "align", "value": "center"}
      ],
      "children": ["step-badge-1", "step-badge-2", "step-badge-3"]
    },
    {
      "id": "step-badge-1",
      "type": "Badge",
      "props": [
        {"key": "text", "value": "1 · Account — current step"},
        {"key": "variant", "value": "default"}
      ],
      "children": []
    },
    {
      "id": "step-badge-2",
      "type": "Badge",
      "props": [
        {"key": "text", "value": "2 · Preferences"},
        {"key": "variant", "value": "outline"}
      ],
      "children": []
    },
    {
      "id": "step-badge-3",
      "type": "Badge",
      "props": [
        {"key": "text", "value": "3 · Done"},
        {"key": "variant", "value": "outline"}
      ],
      "children": []
    },
    {
      "id": "step-panel",
      "type": "Card",
      "props": [
        {"key": "title", "value": "Step 1 · Create your account"},
        {"key": "description", "value": "Tell us who you are. You'll confirm your email on the next step."}
      ],
      "children": ["account-fields", "account-helper"]
    },
    {
      "id": "account-fields",
      "type": "Stack",
      "props": [
        {"key": "direction", "value": "vertical"},
        {"key": "gap", "value": "md"}
      ],
      "children": ["field-name", "field-email", "field-password", "field-terms"]
    },
    {
      "id": "field-name",
      "type": "Input",
      "props": [
        {"key": "label", "value": "Full name"},
        {"key": "placeholder", "value": "e.g. Jordan Meyer"},
        {"key": "type", "value": "text"}
      ],
      "children": []
    },
    {
      "id": "field-email",
      "type": "Input",
      "props": [
        {"key": "label", "value": "Work email"},
        {"key": "placeholder", "value": "you@company.com"},
        {"key": "type", "value": "email"}
      ],
      "children": []
    },
    {
      "id": "field-password",
      "type": "Input",
      "props": [
        {"key": "label", "value": "Password"},
        {"key": "placeholder", "value": "At least 8 characters"},
        {"key": "type", "value": "password"}
      ],
      "children": []
    },
    {
      "id": "field-terms",
      "type": "Checkbox",
      "props": [
        {"key": "label", "value": "I agree to the Terms of Service and Privacy Policy"},
        {"key": "checked", "value": false}
      ],
      "children": []
    },
    {
      "id": "account-helper",
      "type": "Alert",
      "props": [
        {"key": "title", "value": "Your details stay private"},
        {"key": "description", "value": "We only use your email for sign-in and product updates. You can change any of this later in Settings."},
        {"key": "variant", "value": "default"}
      ],
      "children": []
    },
    {
      "id": "wizard-footer",
      "type": "Stack",
      "props": [
        {"key": "direction", "value": "horizontal"},
        {"key": "gap", "value": "md"},
        {"key": "align", "value": "center"}
      ],
      "children": ["btn-back", "btn-next", "footer-note"]
    },
    {
      "id": "btn-back",
      "type": "Button",
      "props": [
        {"key": "label", "value": "Back"},
        {"key": "variant", "value": "outline"}
      ],
      "children": []
    },
    {
      "id": "btn-next",
      "type": "Button",
      "props": [
        {"key": "label", "value": "Next: Preferences"},
        {"key": "variant", "value": "default"}
      ],
      "children": []
    },
    {
      "id": "footer-note",
      "type": "Text",
      "props": [
        {"key": "text", "value": "Step 1 of 3 · Back is disabled on the first step."},
        {"key": "variant", "value": "muted"}
      ],
      "children": []
    }
  ]
}
